import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Cursor","description":"Connect Cursor to Tokeness using an OpenAI API key and Override OpenAI Base URL.","frontmatter":{"title":"Cursor","description":"Connect Cursor to Tokeness using an OpenAI API key and Override OpenAI Base URL."},"headers":[],"relativePath":"integrations/cursor.md","filePath":"integrations/cursor.md","lastUpdated":1783700215000}'),r={name:"integrations/cursor.md"};function n(i,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="cursor" tabindex="-1">Cursor <a class="header-anchor" href="#cursor" aria-label="Permalink to &quot;Cursor&quot;">​</a></h1><p>The custom model entry point in Cursor varies across versions. When you can see settings like OpenAI API Key, Override OpenAI Base URL, or Add Custom Model, you can connect to Tokeness using the OpenAI-compatible method.</p><p>If your current version does not offer these entry points, or if third-party models are unstable in Agent tool calls, switch to Cline, Claude Code, Codex CLI, or OpenCode.</p><h2 id="connection-details" tabindex="-1">Connection details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection details&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>OpenAI API Key</td><td>A key created in the Tokeness console</td></tr><tr><td>Override OpenAI Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>Custom Model Name</td><td>Full model name from the Tokeness model marketplace</td></tr></tbody></table><p>The field names in Cursor may still say &quot;OpenAI&quot;. Once Base URL override is enabled, requests are sent to the address you specify.</p><h2 id="_1-prepare-tokeness" tabindex="-1">1. Prepare Tokeness <a class="header-anchor" href="#_1-prepare-tokeness" aria-label="Permalink to &quot;1. Prepare Tokeness&quot;">​</a></h2><p>Prepare the following first:</p><ol><li>A Cursor-dedicated API key.</li><li>A model name suited for coding tasks.</li><li>Available balance.</li></ol><p>You can name the key:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cursor-local</span></span></code></pre></div><h2 id="_2-open-cursor-model-settings" tabindex="-1">2. Open Cursor model settings <a class="header-anchor" href="#_2-open-cursor-model-settings" aria-label="Permalink to &quot;2. Open Cursor model settings&quot;">​</a></h2><p>In Cursor, go to:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings -&gt; Models</span></span></code></pre></div><p>Find the API Keys, OpenAI API Key, or similar area.</p><h2 id="_3-fill-in-the-api-key-and-base-url" tabindex="-1">3. Fill in the API key and Base URL <a class="header-anchor" href="#_3-fill-in-the-api-key-and-base-url" aria-label="Permalink to &quot;3. Fill in the API key and Base URL&quot;">​</a></h2><ol><li>Enable OpenAI API Key.</li><li>Paste your Tokeness API key.</li><li>Enable <code>Override OpenAI Base URL</code>.</li><li>Set the Base URL to <code>https://n.tokeness.io/v1</code>.</li><li>Save or confirm.</li></ol><p>If Cursor shows a confirmation dialog, confirm that it will send OpenAI requests to the custom Base URL before proceeding.</p><h2 id="_4-add-a-custom-model" tabindex="-1">4. Add a custom model <a class="header-anchor" href="#_4-add-a-custom-model" aria-label="Permalink to &quot;4. Add a custom model&quot;">​</a></h2><p>On the Models page, find Add Custom Model.</p><p>Enter the model name copied from the Tokeness model marketplace. After adding it, disable the default models you do not need, to avoid selecting the wrong one during testing.</p><p>For the first test, use a short prompt:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please reply with a single sentence confirming Cursor is now connected to Tokeness.</span></span></code></pre></div><p>Then check the Tokeness usage logs to confirm the request.</p><h2 id="_5-scope-of-use" tabindex="-1">5. Scope of use <a class="header-anchor" href="#_5-scope-of-use" aria-label="Permalink to &quot;5. Scope of use&quot;">​</a></h2><p>Cursor&#39;s custom Base URL is typically suited for:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Notes</th></tr></thead><tbody><tr><td>Regular chat</td><td>Start with short questions</td></tr><tr><td>Single-file Q&amp;A</td><td>Control the context range</td></tr><tr><td>Small-scale code explanation</td><td>Observe whether the model can reply stably</td></tr></tbody></table><p>For large-scale Agent edits, complex tool calls, and multi-file modifications, compatibility varies across third-party models. Start with small tasks, then expand the scope.</p><h2 id="_6-troubleshooting" tabindex="-1">6. Troubleshooting <a class="header-anchor" href="#_6-troubleshooting" aria-label="Permalink to &quot;6. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Cannot find Override OpenAI Base URL</td><td>The current Cursor version may not support this entry point</td></tr><tr><td>401 Unauthorized</td><td>Re-copy the Tokeness API key</td></tr><tr><td>404 Not Found</td><td>Set Base URL to <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the custom model name from the model marketplace</td></tr><tr><td>No Tokeness logs</td><td>The current model is not using the custom OpenAI configuration</td></tr><tr><td>Chat works but Agent errors</td><td>The model is not fully compatible with Cursor tool calls; switch models or tools</td></tr><tr><td>Still using the default model</td><td>Disable default models or manually select the custom model in the chat sidebar</td></tr></tbody></table><h2 id="external-docs" tabindex="-1">External docs <a class="header-anchor" href="#external-docs" aria-label="Permalink to &quot;External docs&quot;">​</a></h2><ul><li><a href="https://openrouter.ai/docs/cookbook/coding-agents/cursor-integration" target="_blank" rel="noreferrer">OpenRouter Cursor Integration</a></li><li><a href="https://docs.sambanova.ai/docs/en/integrations/cursor" target="_blank" rel="noreferrer">SambaNova Cursor Integration</a></li><li><a href="https://docs.litellm.ai/docs/tutorials/cursor_integration" target="_blank" rel="noreferrer">LiteLLM Cursor Integration</a></li></ul>',32)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
